function selectFirst(f){f.dom.window.document.querySelector('.action-select')?.click();}
function createFixture(html=widgetHtml,options={}){
const action={id:'d2adf59d-e631-4e65-95d2-35a6558d36c5',title:'保存済み',notes:'',revision:1,status:'active',view:'normal',parent_id:null,due_at:null,defer_until:null,defer_reasons:[],order:0,flagged:false,project_id:null};
let state={schemaVersion:2,revision:1,projects:[],tags:[],perspectives:[],actions:[action],list_scopes:{inbox:[action.id],waiting:[],flagged:[]},retrieved_at:'2026-10-01T00:00:00Z'};
let lost=false,lastLost=null;const requests=[],timers=new Map(),frames=new Map();let frameId=0,frameTime=0;
const dom=new JSDOM(html,{url:'https://fictional.invalid',runScripts:'dangerously',beforeParse(w){
 w.requestAnimationFrame=callback=>{const id=++frameId;frames.set(id,callback);return id;};w.cancelAnimationFrame=id=>frames.delete(id);
 const timeout=w.setTimeout.bind(w),clear=w.clearTimeout.bind(w);let timer=100;
 w.setTimeout=(fn,ms)=>{if(ms===20000||ms===500){const n=++timer;timers.set(n,fn);return n;}return timeout(fn,ms);};w.clearTimeout=n=>{timers.delete(n);clear(n);};
 if(options.resizeObserver)w.ResizeObserver=options.resizeObserver;
 w.confirm=()=>true;w.HTMLDialogElement.prototype.showModal=function(){this.open=true;};w.HTMLDialogElement.prototype.close=function(){this.open=false;};
 w.postMessage=m=>{if(m.id==null)return;let result;
 if(m.method==='ui/initialize')result=options.initialize||{};else if(m.method==='ui/request-display-mode'){requests.push({method:m.method,args:structuredClone(m.params)});result={mode:options.actualMode||m.params.mode};}else{const {name,arguments:a}=m.params;requests.push({name,args:structuredClone(a)});
  if(name==='list_actions')result={structuredContent:structuredClone(state)};
  else if(name==='preview_change'&&options.previewError)result={isError:true,structuredContent:{error:options.previewError}};
  else if(name==='preview_change')result={structuredContent:{expectedRevision:state.revision,kind:a.kind,payload:a.kind==='defer'&&a.payload.date?{id:a.payload.id,until:dateDefer(a.payload.date,a.payload.timezone)}:a.payload,affected:[action],warnings:options.warnings||[],evaluatedAt:state.retrieved_at}};
  else if(name==='apply_change'&&a.kind==='add'){if(lost){lastLost=m;return;}const createdId='f25a36bb-3eef-4c21-b3ee-0cc45cb596ab';let created=state.actions.find(x=>x.id===createdId);if(!created){created={...action,...a.payload,id:createdId,title:a.payload.title,notes:a.payload.notes,project_id:a.payload.project_id??null,tags:(a.payload.tag_ids||[]).map(id=>({id,name:state.tags?.find(t=>t.id===id)?.name||id}))};state.actions.push(created);if(created.project_id===null)state.list_scopes.inbox.push(created.id);state.revision++;}result={structuredContent:{...structuredClone(state),result:{operationId:a.operationId,resolved:{actions:[{id:createdId}]}}}};}
  else if(name==='apply_change'&&['project_get_or_create','tag_get_or_create','project_add','tag_add'].includes(a.kind)){if(lost){lastLost=m;return;}const kind=a.kind.startsWith('project')?'project':'tag',catalog=state[kind==='project'?'projects':'tags']||(state[kind==='project'?'projects':'tags']=[]);let record=a.kind.endsWith('_add')?null:catalog.find(n=>n.name===a.payload.name.trim()&&(n.parent_id??null)===(a.payload.parent_id??null));const created=!record;if(!record){record={id:kind==='project'?'63620a50-eaa0-4e5c-8022-a8e84940a6b2':'31879f0d-4a9c-44a6-af42-0f3f5f03b8ce',name:a.payload.name.trim(),description:'',parent_id:a.payload.parent_id??null,order:0};catalog.push(record);state.revision++;}result={structuredContent:{...structuredClone(state),result:{operationId:a.operationId,resolved:{[kind]:{id:record.id,created}}}}};}
  else if(name==='apply_change'&&['project_edit','tag_edit'].includes(a.kind)){if(lost){lastLost=m;return;}const catalog=state[a.kind==='project_edit'?'projects':'tags'],target=catalog.find(n=>n.id===a.payload.id);Object.assign(target,a.payload);if(a.payload.name!==undefined)target.name=a.payload.name.trim();state.revision++;result={structuredContent:{...structuredClone(state),result:{operationId:a.operationId}}};}
  else if(name==='apply_change'){if(lost){lastLost=m;return;}const target=state.actions.find(x=>x.id===a.payload.id)||action;if(a.kind==='action_tag'){target.tags=target.tags||[];if(a.payload.enabled&&!target.tags.some(tag=>tag.id===a.payload.tag_id))target.tags.push({id:a.payload.tag_id});if(!a.payload.enabled)target.tags=target.tags.filter(tag=>tag.id!==a.payload.tag_id);}else if(a.kind==='complete'){target.status='completed';target.view='completed';}else if(a.kind==='release'){target.defer_until=null;target.defer_reasons=[];}else if(a.kind==='defer'){target.defer_until=a.payload.until;}else if(a.kind==='status'){target.status=a.payload.status;state.list_scopes.waiting=target.status==='on-hold'?[target.id]:[];}else{Object.assign(target,a.payload);}state.list_scopes.flagged=target.flagged&&target.view==='normal'?[target.id]:[];target.revision++;state.revision++;result={structuredContent:{...structuredClone(state),result:{operationId:a.operationId}}};}
  else if(name==='capture_intent'){if(lost){lastLost=m;return;}const captured={...action,id:'f25a36bb-3eef-4c21-b3ee-0cc45cb596ab',title:a.title,notes:a.text};state.actions.push(captured);state.list_scopes.inbox.push(captured.id);state.revision++;result={structuredContent:{...structuredClone(state),result:{operationId:a.operationId}}};}
  else if(name==='add_action'){if(lost){lastLost=m;return;}result={structuredContent:{...structuredClone(state),result:{operationId:a.request_id}}};}
  else if(name==='operation_status')result={structuredContent:{status:'not_observed',result:null}};
 }
 queueMicrotask(()=>w.dispatchEvent(new w.MessageEvent('message',{source:w,data:{jsonrpc:'2.0',id:m.id,result}})));
 };
}});
return {action,state,requests,timers,dom,frameCount:()=>frames.size,flushFrames(){for(let count=0;frames.size&&count<20;count++){const callbacks=[...frames.values()];frames.clear();frameTime+=16;for(const callback of callbacks)callback(frameTime);}},setLost:value=>{lost=value;},lostRequest:()=>lastLost};
}
test('verification resource discards real successful write response and preserves exact-ID recovery',async(t)=>{
 const f=createFixture(verificationWidgetHtml);t.after(()=>f.dom.window.close());await settle();selectFirst(f);const d=f.dom.window.document;
 d.getElementById('discardNext').checked=true;d.getElementById('addAction').click();await settle();assert.equal(f.requests.filter(r=>r.args?.kind==='add').length,0);await fillCreation(f);assert.equal(f.requests.filter(r=>r.name==='apply_change'&&r.args.kind==='add').length,1);assert.equal(d.getElementById('discardNext').checked,false);assert.match(d.getElementById('status').textContent,/discarded/);
 for(const fn of [...f.timers.values()])fn();await settle();assert.equal(d.getElementById('unknown').hidden,false);assert.equal(d.querySelector('section input').disabled,false);const first=f.requests.find(r=>r.name==='apply_change'&&r.args.kind==='add');d.getElementById('retry').click();await settle();assert.deepEqual(f.requests.filter(r=>r.name==='apply_change'&&r.args.kind==='add').at(-1).args,first.args);assert.equal(d.getElementById('unknown').hidden,true);
});
