test('control rendering avoids same-value disabled writes and preserves busy and completed states',async t=>{
 const f=createFixture();t.after(()=>f.dom.window.close());await settle();const d=f.dom.window.document,w=f.dom.window,complete=d.querySelector('.complete'),records=[],observer=new w.MutationObserver(changes=>records.push(...changes));assert.equal(complete.disabled,false,'an active action starts enabled');observer.observe(d.getElementById('actions'),{subtree:true,attributes:true,attributeFilter:['disabled']});
 f.setLost(true);complete.click();await settle();assert.equal(complete.disabled,true);assert.equal(records.filter(record=>record.target.classList.contains('complete')).length,1,`a real busy transition should write disabled once; disabled=${complete.disabled}; connected=${complete.isConnected}; records=${records.map(record=>record.target.className+':'+record.attributeName+':'+record.target.disabled+':'+record.target.isConnected)}; request=${f.requests.map(request=>request.name+':'+(request.args?.kind||''))}`);
 records.length=0;w.dispatchEvent(new w.MessageEvent('message',{source:w,data:{jsonrpc:'2.0',method:'ui/notifications/tool-result',params:{structuredContent:structuredClone(f.state)}}}));await settle();assert.equal(records.length,0,'an unchanged busy render must not rewrite disabled');observer.disconnect();
 const completed=createFixture();t.after(()=>completed.dom.window.close());await settle();const cd=completed.dom.window.document;completed.action.status='completed';cd.querySelector('[data-view="history"]').click();cd.getElementById('refresh').click();await settle();const completedControl=cd.querySelector('.complete');assert.equal(completedControl.getAttribute('aria-checked'),'true');assert.equal(completedControl.disabled,true,'a completed action remains disabled after renderControls');
});
test('same-target pointer movement does not rewrite aria-live destination text but a changed target does',async t=>{
 const f=createFixture();t.after(()=>f.dom.window.close());await settle();const d=f.dom.window.document,w=f.dom.window;for(const [id,title] of [['destination-a','Destination A'],['destination-b','Destination B']]){f.state.actions.push({...f.action,id,title,order:f.state.actions.length});f.state.list_scopes.inbox.push(id);}d.getElementById('refresh').click();await settle();
 const rows=[...d.querySelectorAll('.action-row')],source=rows[0],first=rows[1],second=rows[2],status=d.getElementById('moveStatus');d.querySelector('.list-panel').getBoundingClientRect=()=>({left:0,right:300});d.getElementById('actions').getBoundingClientRect=()=>({left:0,right:300});rows.forEach((row,index)=>{const top=index*60;row.getBoundingClientRect=()=>({left:0,right:300,top,bottom:top+60,height:60});row.querySelector('.action-select').getBoundingClientRect=()=>({left:20,right:280,top:top+10,bottom:top+40,height:30});});d.elementFromPoint=(x,y)=>y<60?source.querySelector('.action-select'):y<120?first.querySelector('.action-select'):second.querySelector('.action-select');
 const statusMutations=[],observer=new w.MutationObserver(changes=>statusMutations.push(...changes));observer.observe(status,{childList:true});const pointer=(target,type,x,y)=>{const event=new w.Event(type,{bubbles:true,cancelable:true});Object.defineProperties(event,{pointerId:{value:9},pointerType:{value:'mouse'},button:{value:0},clientX:{value:x},clientY:{value:y}});target.dispatchEvent(event);};pointer(source,'pointerdown',20,30);pointer(w,'pointermove',120,90);f.flushFrames();await settle();const firstStatus=status.textContent;assert.match(firstStatus,/Destination A/,`target status should reflect the first action destination; status=${firstStatus}; drops=${[...d.querySelectorAll('[data-drop-class]')].map(row=>row.dataset.actionId+':'+row.dataset.dropClass)}; frames=${f.frameCount()}; rows=${rows.map(r=>r.dataset.actionId+':'+r.getBoundingClientRect().top+'-'+r.getBoundingClientRect().bottom)}; select=${d.querySelector('.batch-selected')?.dataset.actionId}; active=${d.getElementById('selectionBar').hidden}`);assert(statusMutations.length>0,'initial target should announce its status');statusMutations.length=0;
 pointer(w,'pointermove',122,95);f.flushFrames();await settle();assert.equal(status.textContent,firstStatus);assert.equal(statusMutations.length,0,'same-target movement must not replace aria-live text');
 pointer(w,'pointermove',120,150);f.flushFrames();await settle();assert.match(status.textContent,/Destination B/);assert.notEqual(status.textContent,firstStatus);assert(statusMutations.length>0,'a semantic target change should update the status');observer.disconnect();
});
