test('Refresh state icons distinguish pending, writing and saved without animation and preserve recovery semantics',async t=>{
 const f=createFixture();t.after(()=>f.dom.window.close());await settle();selectFirst(f);const d=f.dom.window.document,w=f.dom.window,refresh=d.getElementById('refresh'),live=d.getElementById('refreshStatus'),row=d.querySelector('.action-row'),notes=d.getElementById('editNotes');
 const shape=()=>refresh.querySelector('svg').innerHTML;const saved=shape();assert.match(saved,/m5 12 4 4 10-10/);f.setLost(true);
 notes.value='Retain this proposal';notes.dispatchEvent(new w.Event('input',{bubbles:true}));assert.equal(refresh.dataset.state,'pending');const pending=shape();assert.notEqual(pending,saved);
 notes.dispatchEvent(new w.Event('blur'));await settle();assert.equal(refresh.dataset.state,'saving');const saving=shape();assert.notEqual(saving,saved);assert.notEqual(saving,pending);assert.equal(live.textContent,'Saving changes');assert.equal(d.getElementById('saveFeedback').textContent,'Saving changes');assert.equal(d.getElementById('saveFeedback').hidden,false);assert.equal(refresh.getAttribute('aria-busy'),'true');assert.equal(d.querySelector('.action-row'),row);assert.equal(d.getElementById('editNotes'),notes);assert.equal(notes.disabled,false);
 const sent=f.requests.find(request=>request.name==='apply_change');assert(sent);for(const callback of [...f.timers.values()])callback();await settle();assert.equal(refresh.dataset.state,'unknown');assert.equal(d.getElementById('saveFeedback').textContent,'Save result unknown');assert.equal(d.getElementById('saveFeedback').hidden,false);assert.notEqual(shape(),saving);assert.equal(d.getElementById('unknown').hidden,false);
 f.setLost(false);d.getElementById('retry').click();await settle();assert.deepEqual(f.requests.filter(request=>request.name==='apply_change').at(-1).args,sent.args);assert.equal(refresh.dataset.state,'saved');assert.equal(shape(),saved);assert.equal(d.getElementById('saveFeedback').hidden,true);assert.equal(d.getElementById('refresh'),refresh);assert.equal(d.getElementById('refreshStatus'),live);assert.equal(refresh.getAttribute('aria-label'),'Refresh');assert.equal(refresh.getAttribute('aria-describedby'),'refreshStatus');assert.equal(refresh.querySelectorAll('svg').length,1);
 const title=d.getElementById('editTitle');title.value='x'.repeat(201);title.dispatchEvent(new w.Event('input',{bubbles:true}));assert.equal(refresh.dataset.state,'error');assert.equal(d.getElementById('saveFeedback').textContent,'Changes need attention');assert.equal(d.getElementById('saveFeedback').hidden,false);assert.equal(d.getElementById('saveFeedback').getAttribute('aria-hidden'),'true');
 const reads=f.requests.filter(request=>request.name==='list_actions').length;refresh.click();await settle();assert.equal(f.requests.filter(request=>request.name==='list_actions').length,reads+1);
});


test('header resize invalidates active drag geometry while unchanged pointer motion retains the cache',async t=>{
 let resized;const observed=[];class ResizeObserver{constructor(callback){resized=callback;}observe(node){observed.push(node);}disconnect(){}}
 const f=createFixture(widgetHtml,{resizeObserver:ResizeObserver});t.after(()=>f.dom.window.close());await settle();const d=f.dom.window.document,w=f.dom.window;
 for(const [index,title] of ['Destination A','Destination B'].entries()){const id='destination-'+index;f.state.actions.push({...f.action,id,title,order:index+1});f.state.list_scopes.inbox.push(id);}d.getElementById('refresh').click();await settle();assert(observed.includes(d.querySelector('header')));
 let offset=0,reads=0;const rows=[...d.querySelectorAll('.action-row')];for(const [index,row] of rows.entries()){row.getBoundingClientRect=()=>{reads++;return {left:0,right:300,top:offset+index*60,bottom:offset+(index+1)*60,height:60};};row.querySelector('.action-select').getBoundingClientRect=()=>({left:20,right:280,top:offset+index*60+10,bottom:offset+index*60+40,height:30});}
 d.getElementById('actions').getBoundingClientRect=()=>({left:0,right:300});d.querySelector('.list-panel').getBoundingClientRect=()=>({left:0,right:300});d.elementFromPoint=(x,y)=>rows[Math.min(rows.length-1,Math.max(0,Math.floor((y-offset)/60)))].querySelector('.action-select');
 const pointer=(target,type,x,y)=>{const event=new w.Event(type,{bubbles:true,cancelable:true});Object.defineProperties(event,{pointerId:{value:9},pointerType:{value:'mouse'},button:{value:0},clientX:{value:x},clientY:{value:y}});target.dispatchEvent(event);};
 pointer(rows[0],'pointerdown',20,30);pointer(w,'pointermove',120,150);f.flushFrames();await settle();assert.match(d.getElementById('moveStatus').textContent,/Destination B/);const measured=reads;pointer(w,'pointermove',121,150);f.flushFrames();await settle();assert.equal(reads,measured);
 offset=60;resized([{target:d.querySelector('header')}]);assert.equal(f.frameCount(),1);f.flushFrames();await settle();assert(reads>measured);assert.match(d.getElementById('moveStatus').textContent,/Destination A/);assert.deepEqual([...d.querySelectorAll('.action-row')],rows);w.dispatchEvent(new w.KeyboardEvent('keydown',{key:'Escape',bubbles:true}));
});
